<?php use App\Core\Html as H; ?>
<section class="card" id="novo"><div class="card-body"><div class="section-heading"><h2 class="h4">Novo lançamento</h2><a href="<?= H::escape($basePath.'/cartoes') ?>">Compra no cartão →</a></div><p class="text-secondary">Registre uma receita ou despesa. Para o crédito, use o cartão para vincular a fatura.</p>
<form method="post" action="<?= H::escape($basePath.'/movimentacoes') ?>" class="row g-3"><?= H::fields($csrfToken) ?>
<div class="col-md-8"><label for="new-description" class="form-label">Descrição</label><input id="new-description" name="descricao" class="form-control" maxlength="200" required value="<?= H::escape($old['descricao'] ?? '') ?>" placeholder="Ex.: Almoço de hoje"></div><div class="col-md-4"><label for="new-value" class="form-label">Valor (R$)</label><input id="new-value" name="valor" class="form-control" inputmode="decimal" required value="<?= H::escape($old['valor'] ?? '') ?>"></div>
<div class="col-md-6"><label for="new-category" class="form-label">Categoria</label><select id="new-category" name="subgrupo_id" class="form-select" required><option value="">Selecione receita ou despesa</option><?php foreach($categories as $c): ?><option value="<?= (int)$c['id'] ?>" <?= (int)($old['subgrupo_id'] ?? 0)===(int)$c['id'] ? 'selected' : '' ?>><?= H::escape(ucfirst($c['tipo']).' · '.$c['grupo_nome'].' · '.$c['nome']) ?></option><?php endforeach; ?></select></div><div class="col-md-6"><label for="new-account" class="form-label">Conta</label><select id="new-account" name="conta_id" class="form-select"><option value="">A definir (somente pendentes)</option><?php foreach($accounts as $a): ?><option value="<?= (int)$a['id'] ?>" <?= (int)($old['conta_id'] ?? 0)===(int)$a['id'] ? 'selected' : '' ?>><?= H::escape($a['nome']) ?></option><?php endforeach; ?></select></div>
<div class="col-md-4"><label for="new-date" class="form-label">Competência</label><input id="new-date" name="data_competencia" type="date" class="form-control" required value="<?= H::escape($old['data_competencia'] ?? date('Y-m-d')) ?>"></div><div class="col-md-4"><label for="new-due" class="form-label">Vencimento</label><input id="new-due" name="data_vencimento" type="date" class="form-control" required value="<?= H::escape($old['data_vencimento'] ?? date('Y-m-d')) ?>"></div><div class="col-md-4"><label for="new-status" class="form-label">Situação</label><select id="new-status" name="status" class="form-select"><option value="pendente" <?= ($old['status'] ?? '')!=='efetivada' ? 'selected' : '' ?>>Pendente</option><option value="efetivada" <?= ($old['status'] ?? '')==='efetivada' ? 'selected' : '' ?>>Realizada</option></select></div>
<div class="col-12"><details open><summary>Pagamento e observações</summary><div class="row g-3 mt-1"><div class="col-md-4"><label for="new-paid" class="form-label">Efetivação (se realizada)</label><input id="new-paid" name="data_efetivacao" type="date" max="<?= date('Y-m-d') ?>" class="form-control" value="<?= H::escape($old['data_efetivacao'] ?? date('Y-m-d')) ?>"></div><div class="col-md-4"><label for="new-method" class="form-label">Meio de pagamento</label><select id="new-method" name="meio_pagamento" class="form-select"><option value="">Não informado</option><?php foreach(['pix'=>'Pix','debito'=>'Débito','dinheiro'=>'Dinheiro','boleto'=>'Boleto','transferencia'=>'Transferência para terceiros','outro'=>'Outro'] as $k=>$n): ?><option value="<?= $k ?>" <?= ($old['meio_pagamento'] ?? '')===$k ? 'selected' : '' ?>><?= $n ?></option><?php endforeach; ?></select></div><div class="col-md-4"><label for="new-notes" class="form-label">Observações</label><input id="new-notes" name="observacao" class="form-control" maxlength="500" value="<?= H::escape($old['observacao'] ?? '') ?>"></div></div></details></div>
<div class="col-12 d-flex gap-3 flex-wrap"><button class="btn btn-uai-primary">Salvar lançamento</button><a class="btn btn-outline-secondary" href="<?= H::escape($basePath.'/movimentacoes/avancado') ?>">Parcelamento fora do cartão</a><a class="btn btn-outline-secondary" href="<?= H::escape($basePath.'/recorrencias#nova') ?>">Criar recorrência</a></div></form></div></section>
